private static int decodeOctets(int i, ByteBuffer bb, StringBuilder sb) {
    while (bb.hasRemaining()) {
        int b = bb.get(i) & 0xFF;
        if ((b & 0x80) == 0) {
            // 1 byte character
            sb.append((char) b);
            i++;
        } else if ((b & 0xE0) == 0xC0) {
            // 2 byte character
            if (bb.remaining() < 2) break;
            int c = (b & 0x1F) << 6 | (bb.get(i + 1) & 0x3F);
            sb.append((char) c);
            i += 2;
        } else if ((b & 0xF0) == 0xE0) {
            // 3 byte character
            if (bb.remaining() < 3) break;
            int c = (b & 0x0F) << 12 | (bb.get(i + 1) & 0x3F) << 6 | (bb.get(i + 2) & 0x3F);
            sb.append((char) c);
            i += 3;
        } else if ((b & 0xF8) == 0xF0) {
            // 4 byte character
            if (bb.remaining() < 4) break;
            int c = (b & 0x07) << 18 | (bb.get(i + 1) & 0x3F) << 12 | (bb.get(i + 2) & 0x3F) << 6 | (bb.get(i + 3) & 0x3F);
            sb.append(Character.toChars(c));
            i += 4;
        } else {
            // Invalid UTF-8 sequence
            i++;
        }
    }
    return i;
}

