private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    int neededSize = (this.data == null) ? 0 : this.data.length;
    if (neededSize + size > Integer.MAX_VALUE) {
        throw new OutOfMemoryError("Requested array size exceeds VM limit");
    }
    neededSize += size;
    byte[] newData = new byte[Math.max(neededSize, 2 * (this.data == null ? 16 : this.data.length))];
    if (this.data != null) {
        System.arraycopy(this.data, 0, newData, 0, this.data.length);
    }
    this.data = newData;
}

