import java.util.LinkedList;

class Bucket {
    private LinkedList<Bucket> list;
    private Bucket prev;
    private Bucket next;

    public Bucket(LinkedList<Bucket> list) {
        this.list = list;
    }

    /** 
     * Inserts this bucket in the data structure before the  {@code bucket}.
     * @param bucket the bucket, that will be the next to this bucket.
     */
    void insertBefore(Bucket bucket) {
        if (bucket == null) {
            throw new IllegalArgumentException("Bucket cannot be null");
        }
        if (bucket.list != this.list) {
            throw new IllegalArgumentException("Buckets are not in the same list");
        }

        this.next = bucket;
        this.prev = bucket.prev;
        if (bucket.prev != null) {
            bucket.prev.next = this;
        }
        bucket.prev = this;

        if (bucket == list.getFirst()) {
            list.addFirst(this);
        }
    }
}

