public static List<PathSegmentImpl> decodePath(URI u, boolean decode) {
    List<PathSegmentImpl> pathSegments = new ArrayList<>();
    String path = u.getPath();

    if (path == null || path.isEmpty()) {
        return pathSegments;
    }

    // Ignore leading slash
    if (path.startsWith("/")) {
        path = path.substring(1);
    }

    StringTokenizer tokenizer = new StringTokenizer(path, "/");
    while (tokenizer.hasMoreTokens()) {
        String segment = tokenizer.nextToken();
        if (decode) {
            // Assuming PathSegmentImpl has a constructor that takes a decoded string
            pathSegments.add(new PathSegmentImpl(java.net.URLDecoder.decode(segment, java.nio.charset.StandardCharsets.UTF_8)));
        } else {
            pathSegments.add(new PathSegmentImpl(segment));
        }
    }

    return pathSegments;
}

