import java.util.Stack;

private void pop(final String descriptor) {
    Stack<Object> outputFrameStack = new Stack<>();
    int index = 0;

    if (descriptor.charAt(0) == '(') {
        // Method descriptor, skip '(' and pop each argument type
        index = 1;
        while (descriptor.charAt(index) != ')') {
            index = popType(descriptor, index, outputFrameStack);
        }
    } else {
        // Type descriptor, pop the single type
        popType(descriptor, index, outputFrameStack);
    }
}

private int popType(final String descriptor, int index, Stack<Object> outputFrameStack) {
    switch (descriptor.charAt(index)) {
        case 'B': case 'C': case 'I': case 'S': case 'Z':
            outputFrameStack.pop();
            index++;
            break;
        case 'D':
            outputFrameStack.pop();
            outputFrameStack.pop();
            index++;
            break;
        case 'F':
            outputFrameStack.pop();
            index++;
            break;
        case 'J':
            outputFrameStack.pop();
            outputFrameStack.pop();
            index++;
            break;
        case 'L':
            // Reference type, pop a single reference
            outputFrameStack.pop();
            index = descriptor.indexOf(';', index) + 1;
            break;
        case '[':
            // Array type, pop a single reference
            outputFrameStack.pop();
            while (descriptor.charAt(index) == '[') {
                index++;
            }
            if (descriptor.charAt(index) == 'L') {
                index = descriptor.indexOf(';', index) + 1;
            } else {
                index++;
            }
            break;
        default:
            throw new IllegalArgumentException("Invalid descriptor: " + descriptor);
    }
    return index;
}

