public static Pair<Box2D, Box2D> splitAlongXAxis(Box2D box) {
    float centerX = box.m_center.x;
    float centerY = box.m_center.y;
    float halfWidth = box.m_halfWidth / 2;
    float height = box.m_halfHeight;

    Box2D leftBox = new Box2D();
    leftBox.m_center.set(centerX - halfWidth, centerY);
    leftBox.m_halfWidth = halfWidth;
    leftBox.m_halfHeight = height;

    Box2D rightBox = new Box2D();
    rightBox.m_center.set(centerX + halfWidth, centerY);
    rightBox.m_halfWidth = halfWidth;
    rightBox.m_halfHeight = height;

    return new Pair<>(leftBox, rightBox);
}

import java.util.Arrays;

private void enlarge(final int size) {
    if (size < 0) {
        throw new IllegalArgumentException("Size must be non-negative");
    }
    int currentCapacity = (this.data == null) ? 0 : this.data.length;
    int requiredCapacity = currentCapacity + size;
    if (requiredCapacity > currentCapacity) {
        int newCapacity = (currentCapacity == 0) ? 64 : currentCapacity * 2;
        while (newCapacity < requiredCapacity) {
            newCapacity *= 2;
        }
        this.data = Arrays.copyOf(this.data, newCapacity);
    }
}

