        if (str == null || searchStrArray == null || searchStrArray.isEmpty()) {
            return false;
        }

        String lowerCaseStr = str.toLowerCase();

        for (String searchStr : searchStrArray) {
            if (searchStr != null && lowerCaseStr.contains(searchStr.toLowerCase())) {
                return true;
            }
        }

        return false;
    }
}

import java.util.Arrays;

public class PrimeUtils {
    public static int nextPrime(int desiredCapacity) {
        if (desiredCapacity <= 1) {
            return 2;
        }
        int candidate = desiredCapacity;
        if (candidate % 2 == 0) {
            candidate++;
        }
        while (!isPrime(candidate)) {
            candidate += 2;
        }
        if (desiredCapacity >= 1000 && candidate > desiredCapacity * 1.11) {
            candidate = findClosePrime(desiredCapacity);
        }
        return candidate;
    }

    private static boolean isPrime(int num) {
        if (num <= 1) return false;
        if (num <= 3) return true;
        if (num % 2 == 0 || num % 3 == 0) return false;
        for (int i = 5; i * i <= num; i += 6) {
            if (num % i == 0 || num % (i + 2) == 0) return false;
        }
        return true;
    }

    private static int findClosePrime(int desiredCapacity) {
        int lowerBound = (int) (desiredCapacity * 0.89);
        int upperBound = (int) (desiredCapacity * 1.11);
        for (int i = desiredCapacity; i <= upperBound; i++) {
            if (isPrime(i)) {
                return i;
            }
        }
        for (int i = desiredCapacity - 1; i >= lowerBound; i--) {
            if (isPrime(i)) {
                return i;
            }
        }
        return desiredCapacity; // Fallback, should not reach here if input is valid
    }

    public static void main(String[] args) {
        System.out.println(nextPrime(1000)); // Example usage
    }
}

