        pathWeight += graph.getEdgeWeight(edge);
        lastVertex = Graphs.getOppositeVertex(graph, edge, currentVertex);
        currentVertex = lastVertex;
    }

    return new GraphWalk<>(graph, startVertex, lastVertex, tour, pathWeight);
}

