public class Graph {
    private Node currentNode;
    private List<Node> nodes;
    private Map<Node, Node> virtualToReal;

    public Graph(List<Node> nodes, Map<Node, Node> virtualToReal) {
        this.nodes = nodes;
        this.virtualToReal = virtualToReal;
        this.currentNode = nodes.get(0);
    }

    public Edge edgeToNext() {
        int currentIndex = nodes.indexOf(currentNode);
        if (currentIndex == -1 || currentIndex >= nodes.size() - 1) {
            return null; // No next node
        }
        Node nextNode = nodes.get(currentIndex + 1);
        Node realCurrentNode = virtualToReal.getOrDefault(currentNode, currentNode);
        Node realNextNode = virtualToReal.getOrDefault(nextNode, nextNode);
        return new Edge(realCurrentNode, realNextNode);
    }
}

public static boolean substringMatch(CharSequence str, int index, CharSequence substring) {
    if (str == null || substring == null) {
        return false;
    }
    if (index < 0 || index + substring.length() > str.length()) {
        return false;
    }
    for (int i = 0; i < substring.length(); i++) {
        if (str.charAt(index + i) != substring.charAt(i)) {
            return false;
        }
    }
    return true;
}

import org.apache.log4j.AppenderSkeleton;
import org.apache.log4j.spi.LoggingEvent;

import java.io.IOException;
import java.io.PrintWriter;
import java.net.Socket;
import java.util.HashSet;
import java.util.Set;

public class ClientAppender extends AppenderSkeleton {
    private Set<Socket> clients = new HashSet<>();

    public void addClient(Socket client) {
        clients.add(client);
    }

    public void removeClient(Socket client) {
        clients.remove(client);
    }

    @Override
    protected void append(LoggingEvent event) {
        String message = this.layout.format(event);
        for (Socket client : clients) {
            try (PrintWriter out = new PrintWriter(client.getOutputStream(), true)) {
                out.println(message);
            } catch (IOException e) {
                // Handle the exception, e.g., remove the client or log the error
                clients.remove(client);
            }
        }
    }

    @Override
    public void close() {
        for (Socket client : clients) {
            try {
                client.close();
            } catch (IOException e) {
                // Handle the exception
            }
        }
        clients.clear();
    }

    @Override
    public boolean requiresLayout() {
        return true;
    }
}

